const api={get s(){return session;},get tracks(){return tracks;},get layout(){return layout;},engine,search:'',sort:{key:'addedAt',direction:-1},zoom:8,importing:false,jsonPurpose:'session',invalidateDeck:i=>{deckTokens[i]++;},releaseGestures:()=>{api.gestures?.releaseAll();for(let i=0;i<4;i++){clearTimeout(midiJogTimers[i]);midiTouch[i]=false;engine.scratch(i,false);engine.roll(i,false);}controllers.resetInputState?.();},...storage,toast,modal,closeModal,save,snapshot,navigateMobile,renderMobile,render,renderDeck,renderMixer,renderSampler,renderRows,getTrack,position,startAudio,applyAll,ensureBuffer,loadDeck,playDeck,seekDeck,cue,hotcue,loopDeck,resizeLoop,syncDeck,selectMaster,disengageSync,refreshSync,updateSyncUI,effectiveRate,toggleDeck,updateTrack,persistExchange,importFiles,setSample,triggerSample,record,removeTrack,replaceValue,updateParamUI,restoreSession,prepareBackupRestore,applyBackupArchive,refreshSamples,resumeSampleRefresh};
