function toast(message,error=false,duration=6500){const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),duration);}
function modal(title,body){$('#dialog-content').innerHTML=dialogFrame(title,body);if(!$('#dialog').open)$('#dialog').showModal();}
function closeModal(){$('#dialog').close();}
function snapshot(){const raw=structuredClone(session);raw.decks.forEach((d,i)=>{if(engine.loadedIds[i]===d.trackId)d.position=engine.positions[i];if(d.syncEnabled&&engine.syncMasters[i]>=0)d.rate=effectiveRate(i);d.playing=false;});raw.savedAt=Date.now();return raw;}
function save(){if(!ready)return;$('#save-status').textContent='保存中…';clearTimeout(saveTimer);saveTimer=setTimeout(saveNow,650);}
async function saveNow(){if(!ready)return;const data=snapshot();saveQueue=saveQueue.catch(()=>{}).then(async()=>{try{await storage.putState(data);storageFailed=false;$('#save-status').textContent='✓ 保存済み';try{localStorage.setItem('orbit-session-recovery',JSON.stringify(data));}catch{}}catch(e){$('#save-status').textContent='保存できません';if(!storageFailed)toast('端末への保存に失敗しました。設定からセッションJSONを書き出してください。容量不足やプライベートモードを確認してください。',true,12000);storageFailed=true;}});return saveQueue;}
function getTrack(i){return tracks.get(session.decks[i].trackId);}
function position(i){return engine.loadedIds[i]===session.decks[i].trackId?engine.positions[i]:session.decks[i].position;}
function effectiveRate(i){return engine.loadedIds[i]===session.decks[i].trackId&&engine.syncMasters[i]>=0?engine.rates[i]:session.decks[i].rate;}
function updateSyncUI(){for(let i=0;i<4;i++){controllers.feedback(`deck.${i}.sync`,session.decks[i].syncEnabled);const enabled=session.decks[i].syncEnabled,status=enabled?(engine.syncMasters[i]<0?'waiting':engine.syncStates[i]||'waiting'):'off',description={off:'MASTERに継続同期',waiting:'MASTERの音源を待機',suspended:'ジョグ・REV・ROLL操作中は同期を一時停止',range:'必要な再生速度が範囲外です',aligning:'拍位置を徐々に同期中',locked:'テンポと拍位置を継続同期中',tempo:'MASTER停止中：テンポを同期'}[status]||'同期を準備中';document.querySelectorAll(`[data-action="sync"][data-deck="${i}"]`).forEach(el=>{el.classList.toggle('active',enabled);el.setAttribute('aria-pressed',String(enabled));el.dataset.syncState=status;el.title=description;el.textContent=enabled&&status==='range'?'SYNC !':enabled&&['waiting','aligning'].includes(status)?'SYNC …':'SYNC';});}}
function disengageSync(i){syncTokens[i]++;const d=session.decks[i];if(d.syncEnabled)d.rate=clamp(effectiveRate(i),.5,1.5);d.syncEnabled=false;if(engine.syncMasters[i]>=0)engine.setSync(i,session.selectedDeck,false);updateSyncUI();}
function refreshSync(){const master=session.selectedDeck,wanted=session.decks.map((d,i)=>i!==master&&d.syncEnabled&&engine.loadedIds[i]===d.trackId&&d.trackId&&engine.loadedIds[master]===session.decks[master].trackId&&session.decks[master].trackId?master:-1);for(let i=0;i<4;i++)if(engine.syncMasters[i]>=0&&engine.syncMasters[i]!==wanted[i])engine.setSync(i,master,false);for(let i=0;i<4;i++)if(wanted[i]>=0&&engine.syncMasters[i]!==wanted[i])engine.setSync(i,master,true);updateSyncUI();}
function loadAudioDeck(i,id,pos=0){assertMutable();engine.load(i,id,pos);engine.setGrid(i,tracks.get(id));engine.applyDeck(i,session.decks[i],tracks.get(id)?.bpm);}
async function ensureSyncBuffers(i){const state=session;for(const deck of [session.selectedDeck,i]){assertMutable();const token=deckTokens[deck],d=session.decks[deck];if(!d.trackId)throw new Error('MASTERと同期先の両方に音源をロードしてください。');await ensureBuffer(d.trackId);if(state!==session||token!==deckTokens[deck])return;if(engine.loadedIds[deck]!==d.trackId)loadAudioDeck(deck,d.trackId,d.position);}}
async function selectMaster(i){assertMutable();disengageSync(i);session.selectedDeck=i;refreshSync();session.decks.forEach((_,j)=>renderDeck(j));for(let j=0;j<4;j++)if(session.decks[j].syncEnabled)await ensureSyncBuffers(j);refreshSync();save();}
function renderMobile(){document.querySelectorAll('button[data-mobile-deck]').forEach(el=>{const i=Number(el.dataset.mobileDeck),t=getTrack(i);el.setAttribute('aria-pressed',session.mobile.deck===i);el.classList.toggle('playing',session.decks[i].playing);el.dataset.bankActive=String(Math.floor(session.mobile.deck/2)===Math.floor(i/2));el.querySelector('small').textContent=t?.name||'音源未ロード';el.title=`DECK ${LETTERS[i]} · ${t?.name||'音源未ロード'}`;});document.querySelectorAll('button[data-mobile-view]').forEach(el=>el.setAttribute('aria-current',el.dataset.mobileView===session.mobile.view?'page':'false'));}
function navigateMobile(change){api.gestures?.releaseAll();session.mobile=normalizeMobile({...session.mobile,...change});document.body.dataset.cueDelete='false';document.body.dataset.sampleEdit='false';document.querySelectorAll('.cue-delete,.sample-edit').forEach(el=>{el.classList.remove('active');el.setAttribute('aria-pressed','false');});renderMobile();renderRows();layout.apply();save();window.scrollTo({top:0,behavior:'instant'});}
function render(){const s=session;$('#workspace').innerHTML=panel('waves',wavesMarkup(s),`<label class="wave-style"><select data-waveform-style aria-label="波形の配色">${[['rgb','RGB'],['3band','3 BAND'],['deck','DECK']].map(([v,label])=>`<option value="${v}" ${s.waveformStyle===v?'selected':''}>${label}</option>`).join('')}</select></label><span class="wave-color-key" data-wave-colors="${s.waveformStyle}"><i>低</i><i>中</i><i>高</i></span><button data-action="zoom-out" aria-label="波形を縮小">−</button><span class="wave-zoom mono" id="wave-zoom">${api.zoom}s</span><button data-action="zoom-in" aria-label="波形を拡大">＋</button>`)+s.decks.map((d,i)=>panel(`deck${i}`,deckMarkup(i,s,getTrack(i),isLandscapeScreen()))).join('')+panel('mixer',mixerMarkup(s),'<button data-action="settings">OUTPUT ↗</button>')+panel('library',libraryMarkup(s,tracks),`<span class="muted mono">${tracks.size} TRACKS</span>`)+panel('sampler',samplerMarkup(s,tracks));renderRows();renderMobile();session.decks.forEach((_,i)=>feedbackDeck(i));updateSyncUI();layout?.apply();document.querySelectorAll('[data-preset]').forEach(el=>el.classList.toggle('active',el.dataset.preset===s.preset));}
function feedbackDeck(i){const d=session.decks[i],t=getTrack(i);for(const key of ['play','cueOn','reverse','slip','keyLock','loop','sync'])controllers.feedback(`deck.${i}.${key}`,key==='play'?d.playing:key==='loop'?d.loop.enabled:key==='sync'?d.syncEnabled:d[key]);for(let j=0;j<8;j++)controllers.feedback(`deck.${i}.hotcue${j}`,t?.cues?.[j]!=null);}
function renderDeck(i){feedbackDeck(i);const host=$(`[data-panel="deck${i}"] .panel-body`);if(host)host.innerHTML=deckMarkup(i,session,getTrack(i),isLandscapeScreen());renderMobile();const deleteButton=host?.querySelector('.cue-delete');if(deleteButton)deleteButton.setAttribute('aria-pressed',document.body.dataset.cueDelete==='true');updateSyncUI();layout?.apply();}
function renderMixer(){const host=$('[data-panel=mixer] .panel-body');if(host)host.innerHTML=mixerMarkup(session);layout?.apply();}
function renderSampler(){const host=$('[data-panel=sampler] .panel-body');if(host)host.innerHTML=samplerMarkup(session,tracks);}
function renderRows(){let list=[...tracks.values()],p=session.playlist;if(p==='favorites')list=list.filter(t=>t.rating>0);else if(p==='history'){const ids=new Set(session.history.map(h=>h.trackId));list=list.filter(t=>ids.has(t.id));}else if(p!=='all'){list=(session.playlists.find(x=>x.id===p)?.tracks||[]).map(id=>tracks.get(id)).filter(Boolean);}const q=api.search.trim().toLocaleLowerCase();if(q)list=list.filter(t=>[t.name,t.artist,t.bpm,t.key,t.comment].join(' ').toLocaleLowerCase().includes(q));if(['all','favorites','history'].includes(p)||api.sort.key!=='addedAt')list.sort((a,b)=>{const x=a[api.sort.key]??'',y=b[api.sort.key]??'';return api.sort.direction*(typeof x==='number'&&typeof y==='number'?x-y:String(x).localeCompare(String(y),'ja'));});if($('#track-rows'))$('#track-rows').innerHTML=trackRows(list,session);if($('#track-count'))$('#track-count').textContent=`${list.length} 曲 · ${time(list.reduce((n,t)=>n+t.duration,0))}`;if($('#track-search')&&$('#track-search').value!==api.search)$('#track-search').value=api.search;}
async function startAudio(){if(audioStarting)return audioStarting;audioStarting=(async()=>{await engine.init();applyAll();if(!routeApplied){try{await engine.setRoute(session.mixer);}catch(e){toast('音声出力を復元できません：'+e.message,true);session.mixer.route='stereo';session.mixer.masterSink='default';session.mixer.cueSink='default';await engine.setRoute(session.mixer);save();}routeApplied=true;}$('#audio-start').textContent='AUDIO ON';$('#audio-start').classList.add('active');api.runtime?.refresh();})();try{await audioStarting;}finally{audioStarting=null;}}
function applyAll(){session.decks.forEach((d,i)=>{engine.setGrid(i,getTrack(i));engine.applyDeck(i,d,getTrack(i)?.bpm);});engine.applyMixer(session.mixer,session.decks);refreshSync();}
function cancelSampleRefresh(){libraryEpoch++;sampleController?.abort();}
function resumeSampleRefresh(){if(sampleDeferred&&!api.restoring&&!api.backupUI?.busy&&!sampleCatalogPaused){if(sampleJob){sampleJob.finally(()=>queueMicrotask(resumeSampleRefresh)).catch(()=>{});return;}sampleDeferred=false;refreshSamples({quiet:true}).catch(()=>{});}}
async function refreshSamples({quiet=false}={}){
 if(api.restoring||api.backupUI?.busy||sampleCatalogPaused){if(quiet){sampleDeferred=true;return [];}assertLibraryWritable();throw new Error('セッションを復元しています。完了までお待ちください。');}
 if(sampleJob)return sampleJob;
 assertLibraryWritable();const state=session,epoch=libraryEpoch;sampleController=new AbortController();const controller=sampleController,timer=setTimeout(()=>controller.abort(),8000);
 const current=()=>state===session&&epoch===libraryEpoch&&!api.restoring&&!sampleCatalogPaused&&!api.backupUI?.busy;
 const job=(async()=>{
  const listed=await discoverSampleTracks({signal:controller.signal});if(!current()){sampleDeferred=true;return [];}
  for(const fresh of listed){
   if(!current()){sampleDeferred=true;return [];}
   const existing=tracks.get(fresh.id),same=existing?.sampleHash===fresh.sampleHash;if(same&&existing.source===fresh.source&&existing.bundled&&!existing.demo)continue;
   const authority={id:fresh.id,source:fresh.source,bundled:true,demo:false,sampleHash:fresh.sampleHash,size:fresh.size,filename:fresh.filename,relativePath:fresh.relativePath,sampleCatalogName:fresh.name,sampleCatalogArtist:fresh.artist,missing:false};
   const updated=existing&&same?Object.assign(existing,authority):normalizeTrack({...fresh,...authority});
   await storage.putTrack(updated);if(!current()){sampleDeferred=true;return [];}
   if(!existing||!same)tracks.set(fresh.id,updated);
  }
  api.samplesError=null;renderRows();renderMobile();const count=$('[data-playlist="all"] span');if(count)count.textContent=String(tracks.size);const header=$('[data-panel="library"] .panel-header .muted');if(header)header.textContent=tracks.size+' TRACKS';
  if(!quiet)toast(`公開サンプル一覧を更新しました（${listed.length}曲）。`);return listed;
 })();sampleJob=job;
 try{return await job;}catch(error){if(epoch!==libraryEpoch){sampleDeferred=true;return [];}api.samplesError=error.name==='AbortError'?'公開サンプル一覧の読み込みがタイムアウトしました。':error.message;if(!quiet)throw new Error(api.samplesError);return [];}finally{clearTimeout(timer);if(sampleJob===job)sampleJob=null;if(sampleController===controller)sampleController=null;}
}
async function ensureBuffer(id){
 assertMutable();if(!id)throw new Error('音源をロードしてください。');if(engine.has(id))return;if(jobs.has(id))return await jobs.get(id);
 const state=session,epoch=libraryEpoch;
 const unchanged=()=>{assertMutable();if(state!==session||epoch!==libraryEpoch)throw new Error('セッションが変更されたため音源の読み込みを中止しました。');};
 const job=(async()=>{
  const t=tracks.get(id);if(!t)throw new Error('音源がライブラリにありません。');await startAudio();unchanged();let blob=await storage.getAudio(id),fetchedBundled=false;
  if(!blob&&t.bundled){assertLibraryWritable();blob=await fetchSampleAudio(t);fetchedBundled=true;}
  if(!blob&&t.demo){const r=await fetch(new URL(t.source,import.meta.url));if(!r.ok)throw new Error('デモ音源を読み込めません。接続を確認してください。');blob=await r.blob();}
  if(!blob)throw new Error('音源ファイルがありません。同じファイルを再登録してください。');unchanged();const decoded=await engine.decode(blob);unchanged();
  if(decoded.duration>3600||decoded.length*decoded.numberOfChannels*4>engine.maxBytes)throw new Error('1時間またはデコード512 MBを超える音源です。');
  if(t.bundled&&(t.samplePending||!t.duration)){
   assertLibraryWritable();const wave=await waveform(decoded);let analysis;
   try{analysis=await analyse(decoded);}catch{analysis={bpm:120,bpmConfidence:0,key:'—',keyConfidence:0,gridOffset:0};}
   const tags=await readAudioMetadata(new File([blob],t.filename||'sample.wav',{type:blob.type}));unchanged();assertLibraryWritable();
   const latest=tracks.get(id)||t,tagMetadata=tags.metadata,edits={};for(const key of ['bpm','key','comment'])if(latest.sampleEdits?.[key]===true)edits[key]=latest[key];if(latest.sampleEdits?.bpm)edits.bpmConfidence=100;if(latest.sampleEdits?.key)edits.keyConfidence=100;
   const updated=normalizeTrack({...latest,...wave,...analysis,...tagMetadata,...edits,sampleEdits:undefined,name:latest.name!==latest.sampleCatalogName?latest.name:tagMetadata.name||latest.name,artist:latest.artist!==latest.sampleCatalogArtist?latest.artist:tagMetadata.artist||latest.artist,duration:decoded.duration,sampleRate:decoded.sampleRate,samplePending:false,missing:false});
   await storage.storeTrack(updated,blob);unchanged();Object.assign(t,updated);if(latest!==t)Object.assign(latest,updated);tracks.set(id,latest);renderRows();renderMobile();
   if(tags.warnings.length)toast('公開サンプルの一部のタグを読み込めませんでした。音声は保存しました。',true);
  }else{
   if(!t.waveform){try{const wave=await waveform(decoded);unchanged();Object.assign(t,wave);await storage.putTrack(t);}catch(error){unchanged();toast('カラー波形を更新できませんでした。音源は再生できます。',true);}}
   if(fetchedBundled){assertLibraryWritable();await storage.storeTrack(t,blob);}
  }
  unchanged();await engine.addBuffer(id,decoded,session.sampler.filter(Boolean).map(p=>p.trackId));
 })();jobs.set(id,job);try{await job;}finally{jobs.delete(id);}
}
async function loadDeck(i,id,force=false){assertMutable();api.runtime?.cancelDeck(i);const d=session.decks[i],t=tracks.get(id);if(!t)throw new Error('音源がありません。');if(d.locked&&!force)throw new Error(`DECK ${LETTERS[i]}をOPENに切り替えてください。`);if(d.playing&&!force)throw new Error(`DECK ${LETTERS[i]}を停止してからロードしてください。`);const token=++deckTokens[i];await ensureBuffer(id);if(token!==deckTokens[i])return;d.trackId=id;d.position=0;d.cuePoint=t.cues?.[0]??0;d.playing=false;d.loop={enabled:false,start:0,end:0};d.reverse=false;disengageSync(i);loadAudioDeck(i,id);refreshSync();engine.applyMixer(session.mixer,session.decks);renderDeck(i);save();toast(`${t.name} → DECK ${LETTERS[i]}`,false,1800);}
async function playDeck(i,on){assertMutable();api.runtime?.cancelDeck(i);const d=session.decks[i];if(!d.trackId)throw new Error('ライブラリから音源をロードしてください。');const desired=on??!d.playing,request=++deckTokens[i];if(desired){await startAudio();await ensureBuffer(d.trackId);if(request!==deckTokens[i])return;if(engine.loadedIds[i]!==d.trackId){loadAudioDeck(i,d.trackId,d.position);}if(d.syncEnabled)await ensureSyncBuffers(i);if(request!==deckTokens[i])return;refreshSync();if(engine.positions[i]>=(getTrack(i)?.duration||0)-.02){engine.seek(i,0);d.position=0;}session.history.push({trackId:d.trackId,at:Date.now(),deck:i});session.history=session.history.slice(-500);}d.playing=desired;engine.play(i,desired);if(!desired)d.position=position(i);renderDeck(i);controllers.feedback(`deck.${i}.play`,desired);api.runtime?.refresh();save();}
function seekDeck(i,pos){assertMutable();const t=getTrack(i);if(!t)return;const p=clamp(pos,0,Math.max(0,t.duration-.001));session.decks[i].position=p;if(engine.loadedIds[i]===t.id)engine.seek(i,p);save();}
async function cue(i){assertMutable();const d=session.decks[i],t=getTrack(i);if(!t)return;if(d.playing){await playDeck(i,false);seekDeck(i,d.cuePoint);}else{d.cuePoint=d.quantize?quantizeTrack(position(i),t):position(i);seekDeck(i,d.cuePoint);toast(`DECK ${LETTERS[i]} CUE ${time(d.cuePoint)}`,false,1800);save();}}
async function hotcue(i,j,remove=false){assertMutable();const t=getTrack(i);if(!t)return;const d=session.decks[i];t.cues||=Array(8).fill(null);if(remove){t.cues[j]=null;if(t.cueDetails)t.cueDetails[j]=null;await updateTrack(t);}else if(t.cues[j]==null){t.cues[j]=clamp(d.quantize?quantizeTrack(position(i),t):position(i),0,t.duration);await updateTrack(t);}else{await ensureBuffer(d.trackId);if(engine.loadedIds[i]!==d.trackId){loadAudioDeck(i,d.trackId,d.position);}seekDeck(i,t.cues[j]);const marker=t.cueDetails?.[j];if(marker?.type==='loop'&&marker.end>t.cues[j]){d.loop={enabled:true,start:t.cues[j],end:marker.end};engine.applyDeck(i,d,t.bpm);}else if(d.loop.enabled&&(t.cues[j]<d.loop.start||t.cues[j]>=d.loop.end)){d.loop.enabled=false;engine.applyDeck(i,d,t.bpm);}if(!d.playing)await playDeck(i,true);}refreshSync();renderDeck(i);controllers.feedback(`deck.${i}.hotcue${j}`,t.cues[j]!=null);save();}
function loopDeck(i){assertMutable();const d=session.decks[i],t=getTrack(i);if(!t)return;if(d.loop.enabled)d.loop.enabled=false;else{const start=clamp(d.quantize?quantizeTrack(position(i),t):position(i),0,t.duration-.02);d.loop={enabled:true,start,end:Math.min(t.duration,advanceBeats(start,d.loopBeats,t))};if(d.loop.enabled)seekDeck(i,start);}engine.applyDeck(i,d,t.bpm);renderDeck(i);save();}
function resizeLoop(i,mult){assertMutable();const d=session.decks[i],t=getTrack(i);d.loopBeats=clamp(d.loopBeats*mult,.125,128);if(d.loop.enabled&&t)d.loop.end=Math.min(t.duration,advanceBeats(d.loop.start,d.loopBeats,t));engine.applyDeck(i,d,t?.bpm);renderDeck(i);save();}
async function syncDeck(i){assertMutable();if(i===session.selectedDeck){toast('同期先のデッキでSYNCを押してください。MASTERを基準に合わせます。');return;}const d=session.decks[i];if(d.syncEnabled){disengageSync(i);engine.applyDeck(i,d,getTrack(i)?.bpm);renderDeck(i);save();return;}const token=++syncTokens[i];d.syncEnabled=true;renderDeck(i);try{await ensureSyncBuffers(i);if(syncTokens[i]!==token)return;refreshSync();renderDeck(i);save();}catch(e){if(syncTokens[i]===token){disengageSync(i);renderDeck(i);save();}throw e;}}
function toggleDeck(i,key){assertMutable();if(!['keyLock','reverse','slip','quantize','cueOn'].includes(key))return;const d=session.decks[i];d[key]=!d[key];engine.applyDeck(i,d,getTrack(i)?.bpm);renderDeck(i);if(key==='cueOn'){renderMixer();if(d.cueOn&&session.mixer.route==='stereo')toast('CUEを有効にしました。聴くには設定でCUE出力を選んでください。');}controllers.feedback(`deck.${i}.${key}`,d[key]);save();}
async function updateTrack(t){assertLibraryWritable();t=normalizeTrack(t);tracks.set(t.id,t);try{await storage.putTrack(t);}catch(e){toast('曲情報を保存できませんでした。セッションを書き出してください。',true);throw e;}session.decks.forEach((d,i)=>{if(d.trackId===t.id){engine.setGrid(i,t);engine.applyDeck(i,d,t.bpm);renderDeck(i);}});renderRows();save();}
async function persistExchange(updated,playlists){assertLibraryWritable();clearTimeout(saveTimer);await saveQueue.catch(()=>{});const next=snapshot();next.playlists=[...session.playlists,...playlists];await storage.commitLibrary(updated,next);updated.forEach(t=>tracks.set(t.id,t));session.playlists.push(...playlists);save();}
async function importFiles(files){assertLibraryWritable();if(api.importing){toast('音源の取り込みが終わるまでお待ちください。');return;}const supported=Array.from(files).filter(f=>f.type.startsWith('audio/')||/\.(wav|mp3|flac|aiff?|m4a|ogg|opus|aac|webm|mp4)$/i.test(f.name));if(!supported.length)throw new Error('音声ファイルを選んでください。');api.importing=true;let ok=0,retained=0;const failures=[],metadataWarnings=[];try{await startAudio();for(let index=0;index<supported.length;index++){const f=supported[index];$('#storage-status').textContent=`取り込み ${index+1}/${supported.length} · ${f.name}`;try{if(f.size>300*1024*1024)throw new Error('1ファイル300 MBを超えています。');const candidates=[...tracks.values()].filter(t=>!t.demo&&t.filename===f.name&&t.size===f.size),relativePath=f.webkitRelativePath||'';if(!relativePath&&candidates.length>1)throw new Error('同名・同サイズの曲が複数あります。音源フォルダーから追加してください。');const exists=relativePath?candidates.find(t=>t.relativePath===relativePath)||(candidates.length===1&&!candidates[0].relativePath?candidates[0]:null):candidates[0];if(exists){const updated={...exists,missing:false,...(relativePath?{relativePath}:{})};await storage.storeTrack(updated,f);Object.assign(exists,updated);if(!ok)session.selectedTrack=exists.id;ok++;retained++;continue;}const decoded=await engine.decode(f);if(decoded.duration>3600||decoded.length*decoded.numberOfChannels*4>engine.maxBytes)throw new Error('1時間またはデコード512 MBを超える音源です。');const wave=await waveform(decoded);let result;try{result=await analyse(decoded);}catch{result={bpm:120,bpmConfidence:0,key:'—',keyConfidence:0,gridOffset:0};toast(`${f.name}：BPMを手入力してください。`,true);}const tags=await readAudioMetadata(f);metadataWarnings.push(...tags.warnings.map(w=>`${f.name}: ${w}`));const id=crypto.randomUUID(),name=f.name.replace(/\.[^.]+$/,''),parts=name.split(' - ');const t=normalizeTrack({id,name:parts.length>1?parts.slice(1).join(' - '):name,artist:parts.length>1?parts[0]:'',filename:f.name,relativePath,size:f.size,duration:decoded.duration,sampleRate:decoded.sampleRate,addedAt:Date.now(),...wave,...result,cues:Array(8).fill(null),rating:0,comment:'',...tags.metadata});await storage.storeTrack(t,f);tracks.set(id,t);if(!ok)session.selectedTrack=id;ok++;renderRows();}catch(e){failures.push(`${f.name}: ${e.message}`);}}render();save();toast(`${ok}曲をこの端末に保存しました。`,false,6000);if(failures.length||metadataWarnings.length||retained)modal('取り込み結果',`<p>${ok}曲を保存しました。</p>${retained?`<p>既存の${retained}曲は編集情報を保持しました。MP3のタグを読み直す場合は、ライブラリで選択して「他ソフトとのファイル交換 → 選択曲のMP3タグを再読み込み」を使ってください。</p>`:''}${failures.length?`<h3>音源を保存できなかった曲</h3><ul>${failures.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`:''}${metadataWarnings.length?`<h3>一部のタグを読み込めなかった曲</h3><p>音声データは保存しています。</p><ul>${metadataWarnings.slice(0,100).map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`:''}`);}finally{api.importing=false;$('#storage-status').textContent='音源はこの端末内で処理';}}
async function setSample(i,p){assertMutable();if(p)await ensureBuffer(p.trackId);assertMutable();session.sampler[i]=p;renderSampler();save();}
async function triggerSample(i){assertMutable();const p=session.sampler[i];if(!p){await showSampleEditor(api,i);return;}await ensureBuffer(p.trackId);assertMutable();engine.sample(i,p);}
async function record(){assertMutable();if(recordBusy)return;recordBusy=true;try{if(engine.recording){await engine.stopRecording();}else{await startAudio();assertMutable();await engine.startRecording();$('#record-button').classList.add('is-recording');api.runtime?.refresh();toast('MASTER出力を録音し、この端末へ順次保存しています。RECで停止します。');}}finally{recordBusy=false;}}
async function removeTrack(id){assertLibraryWritable();const t=tracks.get(id);if(!t)return;if(t.demo)throw new Error('デモ音源は削除できません。クレートで表示を分けられます。');if(session.decks.some(d=>d.trackId===id&&d.playing))throw new Error('再生中の音源は削除できません。');await storage.deleteTrack(id);tracks.delete(id);session.decks.forEach((d,i)=>{if(d.trackId===id){d.trackId=null;d.position=0;disengageSync(i);loadAudioDeck(i,null);}});session.playlists.forEach(p=>p.tracks=p.tracks.filter(x=>x!==id));session.sampler=session.sampler.map(p=>p?.trackId===id?null:p);engine.stopSamples();render();save();}
function replaceValue(i,key,value){assertMutable();const d=session.decks[i];if(key==='rate')disengageSync(i);const bounds={rate:[.5,1.5],pitch:[-12,12],volume:[0,1],gain:[-24,12],low:[-30,12],mid:[-30,12],high:[-30,12],filter:[-1,1],'fx.mix':[0,1],'fx.beats':[.125,4]};if(bounds[key])value=clamp(value,...bounds[key]);if(key==='pitch')value=Math.round(value);if(key.startsWith('fx.'))d.fx[key.slice(3)]=key==='fx.type'?value:Number(value);else d[key]=key==='assign'?value:Number(value);engine.applyDeck(i,d,getTrack(i)?.bpm);engine.applyMixer(session.mixer,session.decks);save();}
function updateParamUI(i,key,value){const input=$(`[data-deck="${i}"][data-param="${key}"]`);if(input&&document.activeElement!==input)input.value=value;const out=$(`[data-value="deck.${i}.${key}"]`);if(out)out.textContent=key==='rate'?`${((value-1)*100).toFixed(2)}%`:Number(value).toFixed(key==='filter'?2:1);const knob=input?.closest('.knob');if(knob)knob.style.setProperty('--angle',`${(value-Number(input.min))/(Number(input.max)-Number(input.min))*270-135}deg`);}
async function control(target,value,meta={}){if(api.restoring)return;try{const parts=target.split('.'),trigger=meta.pressed??value>0;if(parts[0]==='mixer'){const k=parts[1],v=k==='crossfader'?value*2-1:value;session.mixer[k]=meta.relative?clamp(session.mixer[k]+value*.01,k==='crossfader'?-1:0,1):v;engine.applyMixer(session.mixer,session.decks);const input=$(`[data-mixer="${k}"]`);if(input)input.value=session.mixer[k];save();return;}if(parts[0]==='sampler'){if(trigger)await triggerSample(Number(parts[1]));return;}const i=Number(parts[1]),key=parts[2],d=session.decks[i];if(!d)return;if(key.startsWith('hotcue')){if(trigger)await hotcue(i,Number(key.slice(6)));return;}if(key==='jog'){if(meta.relative){clearTimeout(midiJogTimers[i]);if(midiTouch[i]){engine.scratch(i,true,clamp(value*.35,-8,8));midiJogTimers[i]=setTimeout(()=>{if(midiTouch[i])engine.scratch(i,true,0);},80);}else if(d.playing){disengageSync(i);engine.applyDeck(i,{...d,rate:d.rate*(1+clamp(value*.015,-.2,.2))},getTrack(i)?.bpm);midiJogTimers[i]=setTimeout(()=>engine.applyDeck(i,session.decks[i],getTrack(i)?.bpm),90);}else seekDeck(i,position(i)+value*.03);}else seekDeck(i,value*(getTrack(i)?.duration||0));return;}if(key==='scratch'){midiTouch[i]=value>0;engine.scratch(i,midiTouch[i],0);return;}if(['play','cue','sync','loop','reverse','slip','keyLock','cueOn'].includes(key)){if(!trigger)return;if(key==='play')await playDeck(i);else if(key==='cue')await cue(i);else if(key==='sync')await syncDeck(i);else if(key==='loop')loopDeck(i);else toggleDeck(i,key);return;}const bounds={rate:[.5,1.5],pitch:[-12,12],volume:[0,1],gain:[-24,12],low:[-30,12],mid:[-30,12],high:[-30,12],filter:[-1,1],fx:[0,1]},b=bounds[key];if(!b)return;const actual=key==='fx'?'fx.mix':key,old=key==='fx'?d.fx.mix:d[key],v=meta.relative?clamp(old+value*(b[1]-b[0])*.005,...b):b[0]+value*(b[1]-b[0]);replaceValue(i,actual,key==='pitch'?Math.round(v):v);updateParamUI(i,actual,v);}catch(e){toast(e.message,true);}}
async function restoreSession(raw){assertLibraryWritable();sampleCatalogPaused=true;cancelSampleRefresh();try{await sampleJob?.catch(()=>{});api.runtime?.reset();api.releaseGestures();if(engine.recording)throw new Error('録音を停止してからセッションを読み込んでください。');const next=normalizeSession(raw.session||raw);for(let i=0;i<4;i++){deckTokens[i]++;syncTokens[i]++;}engine.stopSamples();session.decks.forEach((_,i)=>engine.play(i,false));if(Array.isArray(raw.tracks))for(const t of raw.tracks){if(!t||typeof t.id!=='string')continue;const existing=tracks.get(t.id);if(existing){const updated=normalizeTrack({...existing,...t,source:existing.source,demo:existing.demo,bundled:existing.bundled,sampleHash:existing.sampleHash,missing:existing.missing});tracks.set(t.id,updated);await storage.putTrack(updated);}else if(!t.demo){const restored=normalizeTrack({...t,missing:!(await storage.getAudio(t.id))});tracks.set(t.id,restored);await storage.putTrack(restored);}}session=next;session.decks.forEach((d,i)=>{if(!tracks.has(d.trackId))d.trackId=null;loadAudioDeck(i,null,0);});routeApplied=false;applyAll();render();layout.tools();save();toast('セッションを復元しました。音源・出力を確認してから再生してください。');}finally{sampleCatalogPaused=false;resumeSampleRefresh();}}

function assertMutable(){if(api.restoring)throw new Error('バックアップを復元しています。完了までお待ちください。');}
function assertLibraryWritable(){assertMutable();if(api.backupUI?.busy)throw new Error('バックアップ処理中は音源・曲情報を変更できません。完了までお待ちください。');}
async function prepareBackupRestore(){
 if(engine.recording||engine.recordingStarting||recordBusy||api.importing)throw new Error('録音・読み込みを終了してから復元してください。');
 cancelSampleRefresh();const wasReady=ready;api.restoring=true;api.importing=true;ready=false;clearTimeout(saveTimer);
 const release=()=>{api.restoring=false;api.importing=false;ready=wasReady;api.runtime?.refresh();save();resumeSampleRefresh();};
 try{
  api.runtime?.reset();api.releaseGestures();
  for(let i=0;i<4;i++){deckTokens[i]++;syncTokens[i]++;session.decks[i].position=position(i);session.decks[i].playing=false;engine.play(i,false);}
  engine.stopSamples();render();
  await saveQueue.catch(()=>{});await Promise.allSettled([...jobs.values(),...(sampleJob?[sampleJob]:[]),...(audioStarting?[audioStarting]:[])]);clearTimeout(saveTimer);
  return release;
 }catch(error){release();throw error;}
}
async function applyBackupArchive(archive){
 clearTimeout(saveTimer);api.runtime?.reset();
 for(let i=0;i<4;i++){deckTokens[i]++;syncTokens[i]++;engine.load(i,null,0);}
 engine.stopSamples();for(const id of engine.buffers.keys())engine.send({type:'unload',id});engine.buffers.clear();jobs.clear();
 archive.tracks.forEach(t=>tracks.set(t.id,normalizeTrack(t)));session=normalizeSession(archive.session);session.savedAt=archive.session.savedAt;
 try{localStorage.setItem('orbit-session-recovery',JSON.stringify(archive.session));}catch{}
 routeApplied=false;applyAll();render();layout.tools();$('#save-status').textContent='✓ 保存済み';
}

engine.addEventListener('recording-stopped',e=>{$('#record-button').classList.remove('is-recording');api.runtime?.refresh();toast(e.detail?.error?'録音を中断しました。保存済みの部分を録音一覧から書き出せます。':'録音をこの端末に保存しました。録音一覧から書き出せます。',!!e.detail?.error);if(!api.backupUI?.busy)api.backupUI?.showRecordings().catch(error=>toast(error.message,true));});
engine.addEventListener('ended',e=>{const i=e.detail;session.decks[i].playing=false;session.decks[i].position=engine.positions[i];renderDeck(i);api.runtime?.refresh();save();});engine.addEventListener('error',e=>toast(e.detail,true));engine.addEventListener('state',e=>{$('#engine-status').textContent=e.detail==='running'?`AUDIOWORKLET · ${Math.round(engine.context.sampleRate/1000)} kHz`:'AUDIO '+e.detail.toUpperCase();if(e.detail!=='running')$('#audio-start').textContent='オーディオ再開';});
let renderedLandscape=isLandscapeScreen();window.addEventListener('resize',()=>{const next=isLandscapeScreen();if(ready&&next!==renderedLandscape){renderedLandscape=next;render();}});
window.addEventListener('pagehide',()=>{if(api.restoring)return;try{localStorage.setItem('orbit-session-recovery',JSON.stringify(snapshot()));}catch{}saveNow();});window.addEventListener('beforeunload',e=>{if(engine.recording||engine.recordingStarting||engine.recordingStopping||api.importing||api.backupUI?.busy){e.preventDefault();e.returnValue='';}});
async function boot(){try{const [saved,stored]=await Promise.all([storage.getState(),storage.getTracks()]);stored.forEach(t=>{try{tracks.set(t.id,normalizeTrack(t));}catch{}});let raw=saved;try{const recovery=JSON.parse(localStorage.getItem('orbit-session-recovery')||'null');if(recovery?.savedAt>(saved?.savedAt||0))raw=recovery;}catch{}if(raw)try{session=normalizeSession(raw);}catch{toast('保存された設定を読み込めません。初期配置で開始します。',true);}session.decks.forEach(d=>{if(d.trackId&&!tracks.has(d.trackId)){d.trackId=null;d.position=0;}});}catch{toast('端末ストレージを開けません。今回の変更は保存されません。',true,12000);storageFailed=true;}ready=true;render();layout=new LayoutManager($('#workspace'),()=>session,save,toast);layout.apply();$('#save-status').textContent=storageFailed?'保存不可':'✓ 保存済み';attachEvents(api);api.backupUI=attachBackupUI(api);attachControllerUI(api);api.runtime=createRuntime(api);startVisuals(api);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});registerTools(api);refreshSamples({quiet:true}).catch(()=>{});}
boot().catch(e=>toast('起動に失敗しました：'+e.message,true,20000));
